theme.css:
/* ==== INTERFACE ====
   token  --bg #f1f4f8          整页底色（冷铝灰底，投影高清晰度）
   token  --text #152232        正文与高对比主字（冷深青炭）
   token  --muted #596b82       次级说明、坐标轴与结构线（对比度>4.5:1）
   token  --focus #0d5cb6       键盘焦点与激活轮廓
   token  --panel-bg #ffffff    面板实体底色（明晰抬升）
   token  --pos #1d63b8         数据样本+1正类、正向投票区
   token  --neg #c33a25         数据样本-1负类、负向投票区
   token  --focus-pt #d97706    错分重点聚焦、样本重赋权突显（小面积强调）
   token  --split #2a3b4c       弱分类器划分界线与决策树桩
   token  --fs-h1 34px          页主标题
   token  --fs-h2 22px          区域标题与卡片主标
   token  --fs-lead 19px        导语与核心提问
   token  --fs-body 18px        正文成句叙述
   token  --fs-sec 16px         次级成句说明与参数释义
   token  --fs-label 15px       控件标签、图例、属性指示
   token  --fs-tick 13px        坐标轴纯数字刻度与代码标号
   版心   1488×844              #stage 内尺寸，已含 56px/28px 内衬
   版式   .focus                标题后单一全幅主图/交互区
   版式   .split                左右均分对等对照区
   版式   .aside                主展示区(宽) + 侧边操作监控栏(窄)
   组件   .panel                实底卡片、数值监控器与仪器框
   组件   .panel.q              无填色等边距框（推导与轻量容器）
   组件   .big                  高阶主读数（含 .sm 与 .lg 变体）
   组件   .num                  等宽数字排印与指标数值
   组件   .unit                 数值跟随单位
   组件   .btn                  操作按钮（含 active, focus, disabled 态）
   组件   .btns                 按钮横向组合排布组
   组件   .ctl                  输入控制项与滑杆容器
   组件   .hint                 操作指示与微交互引导语
   组件   .tag                  状态标签与类别药丸
   组件   .legend               图例容器（含 .li 单元与 .sw 色块）
   组件   .cvbox                图表/画布专用裁切容器
   组件   .quiz                 判断题与作答选择器
   组件   .opt                  选项单项（支持选中态与结果反馈）
   组件   .fb                   作答反馈与逻辑解析
   组件   .lead                 导语段落
   组件   .small                注记成句段落
   组件   .note                 方法与算法注意约束框
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  --bg: #f1f4f8;
  --text: #152232;
  --muted: #596b82;
  --focus: #0d5cb6;
  --panel-bg: #ffffff;

  --pos: #1d63b8;
  --neg: #c33a25;
  --focus-pt: #d97706;
  --split: #2a3b4c;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans CJK SC", "Microsoft YaHei", sans-serif;
  --font-mono: "SF Mono", "Cascadia Code", "JetBrains Mono", Consolas, Menlo, monospace;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
  box-sizing: border-box;
  width: 1600px;
  height: 900px;
  overflow: hidden;
}

/* 基础文字与排版标尺 */
h1, .fs-h1 {
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  margin: 0;
  color: var(--text);
}

h2, .fs-h2 {
  font-size: var(--fs-h2);
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--text);
}

.lead {
  font-size: var(--fs-lead);
  line-height: 1.45;
  color: var(--text);
  margin: 0;
}

.small {
  font-size: var(--fs-sec);
  line-height: 1.4;
  color: var(--muted);
  margin: 0;
}

.note {
  font-size: var(--fs-sec);
  line-height: 1.4;
  background: rgba(217, 119, 6, 0.08);
  border-left: 3px solid var(--focus-pt);
  padding: 10px 16px;
  color: var(--text);
  border-radius: 0 4px 4px 0;
}

/* 结构版式 */
.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.split {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  min-height: 0;
}

.aside {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 28px;
  min-height: 0;
}

/* 容器面板 */
.panel {
  background: var(--panel-bg);
  border: 1px solid var(--muted);
  border-radius: 6px;
  padding: 20px 24px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
}

.panel.q {
  background: transparent;
  border: 1px dashed var(--muted);
  border-radius: 6px;
  padding: 20px 24px;
  box-sizing: border-box;
}

.cvbox {
  position: relative;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--muted);
  background: var(--panel-bg);
}

/* 读数与数值 */
.num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.big {
  font-family: var(--font-mono);
  font-size: 40px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.big.sm {
  font-size: 28px;
}

.big.lg {
  font-size: 56px;
}

.unit {
  font-size: var(--fs-sec);
  font-weight: 400;
  color: var(--muted);
  margin-left: 4px;
}

/* 操作控件 */
.btns {
  display: flex;
  gap: 12px;
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 42px;
  padding: 0 18px;
  background: var(--panel-bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
  border: 1px solid var(--muted);
  border-radius: 4px;
  cursor: pointer;
  outline: none;
  user-select: none;
}

.btn:hover:not(:disabled) {
  border-color: var(--text);
}

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn.active, .btn[aria-pressed="true"] {
  background: var(--text);
  color: var(--panel-bg);
  border-color: var(--text);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ctl {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ctl label {
  font-size: var(--fs-label);
  font-weight: 500;
  color: var(--text);
}

.ctl input[type="range"] {
  accent-color: var(--focus);
  width: 100%;
  height: 6px;
  background: rgba(89, 107, 130, 0.25);
  border-radius: 3px;
  outline: none;
}

.hint {
  font-size: var(--fs-sec);
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* 标记、指示与图例 */
.tag {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  font-size: var(--fs-label);
  font-family: var(--font-mono);
  border-radius: 3px;
  border: 1px solid currentColor;
  line-height: 1.2;
}

.tag.pos {
  color: var(--pos);
  background: rgba(29, 99, 184, 0.08);
}

.tag.neg {
  color: var(--neg);
  background: rgba(195, 58, 37, 0.08);
}

.tag.focus-pt {
  color: var(--focus-pt);
  background: rgba(217, 119, 6, 0.1);
}

.legend {
  display: flex;
  gap: 18px;
  align-items: center;
  font-size: var(--fs-label);
  color: var(--text);
}

.legend .li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend .sw {
  width: 12px;
  height: 12px;
  border-radius: 2px;
  flex-shrink: 0;
}

.legend .sw.line {
  width: 16px;
  height: 3px;
  border-radius: 0;
}

/* 作答交互 */
.quiz {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.opt {
  display: flex;
  align-items: center;
  padding: 12px 18px;
  border: 1px solid var(--muted);
  border-radius: 4px;
  background: var(--panel-bg);
  cursor: pointer;
  font-size: var(--fs-body);
  user-select: none;
}

.opt:hover {
  border-color: var(--text);
}

.opt.selected {
  border-color: var(--focus);
  background: rgba(13, 92, 182, 0.06);
}

.fb {
  font-size: var(--fs-sec);
  padding: 12px 16px;
  border-radius: 4px;
  background: rgba(89, 107, 130, 0.1);
  color: var(--text);
  border-left: 3px solid var(--muted);
}

.fb.correct {
  border-left-color: var(--pos);
  background: rgba(29, 99, 184, 0.08);
}

.fb.incorrect {
  border-left-color: var(--neg);
  background: rgba(195, 58, 37, 0.08);
}

/* SVG 尺寸规整 */
svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
